<template>
  <Teleport to="body">
    <Transition name="course-change-layer">
      <div v-if="modelValue" class="course-change-layer" @keydown="handleKeydown">
        <button type="button" class="course-change-backdrop" :aria-label="t('courseEvolution.workspace.close', '关闭课程修改工作台')" @click="close" />
        <section ref="workspaceRef" class="course-change-workspace" role="dialog" aria-modal="true" :aria-labelledby="titleId" tabindex="-1">
          <header class="workspace-header">
            <span class="workspace-mark"><GitBranchPlus :size="19" /></span>
            <div class="workspace-title"><small>{{ t('courseEvolution.workspace.kicker', '课程发布后维护') }}</small><h2 :id="titleId">{{ t('courseEvolution.workspace.title', '全课联动修改') }}</h2></div>
            <div class="course-identity" :title="courseLabel"><BookOpenText :size="15" /><span>{{ courseLabel }}</span></div>
            <button type="button" class="icon-action" :title="t('courseEvolution.workspace.refresh', '重新读取课程资产')" :aria-label="t('courseEvolution.workspace.refresh', '重新读取课程资产')" :disabled="store.loading || store.contextLoading" @click="reloadWorkspace"><RefreshCw :size="17" :class="{ spinning: store.loading || store.contextLoading }" /></button>
            <button type="button" class="icon-action" :title="t('courseEvolution.workspace.close', '关闭课程修改工作台')" :aria-label="t('courseEvolution.workspace.close', '关闭课程修改工作台')" @click="close"><X :size="19" /></button>
          </header>

          <nav class="journey" :aria-label="t('courseEvolution.workspace.journeyLabel', '课程修改流程')">
            <ol>
              <li v-for="step in journeySteps" :key="step.index" :class="{ active: step.index === currentJourneyStep, complete: step.index < currentJourneyStep }" :aria-current="step.index === currentJourneyStep ? 'step' : undefined">
                <span><Check v-if="step.index < currentJourneyStep" :size="13" /><template v-else>{{ step.index }}</template></span><b>{{ step.label }}</b>
              </li>
            </ol>
          </nav>

          <div v-if="workspaceState !== 'request' && workspaceState !== 'scanning'" class="workspace-context-stack">
            <section class="request-context">
              <div><small>{{ t('courseEvolution.workspace.teacherRequest', '老师原话') }}</small><p :title="rawRequest">{{ rawRequest }}</p></div>
              <div><small>{{ t('courseEvolution.workspace.aiInterpretation', 'AI 当前理解') }}</small><p :title="interpretedGoal">{{ interpretedGoal }}</p></div>
              <button v-if="workspaceState !== 'applied'" type="button" @click="openCorrection"><PencilLine :size="14" />{{ t('courseEvolution.workspace.adjustUnderstanding', '修正理解') }}</button>
            </section>

            <form v-if="correctionOpen" class="correction-bar" @submit.prevent="submitCorrection">
              <label><span>{{ t('courseEvolution.workspace.correctionLabel', '直接指出哪里理解错了') }}</span><textarea v-model="correctionText" rows="2" :placeholder="t('courseEvolution.workspace.correctionPlaceholder', '例如：不是删除案例，而是移到新章节，并保留原始资料。')" /></label>
              <div><button type="button" class="button-quiet" @click="correctionOpen = false">{{ t('common.cancel', '取消') }}</button><button type="submit" class="button-primary" :disabled="store.generating || !correctionText.trim()"><LoaderCircle v-if="store.generating" :size="15" class="spinning" /><Sparkles v-else :size="15" />{{ t('courseEvolution.workspace.submitCorrection', '重新分析') }}</button></div>
            </form>
            <p v-if="actionError" class="workspace-status-error" role="alert"><TriangleAlert :size="15" />{{ actionError }}</p>
          </div>

          <div class="workspace-stage">
            <main v-if="workspaceState === 'request'" class="request-state">
              <section class="request-composer">
                <div class="request-heading"><div><span>{{ t('courseEvolution.workspace.requestStep', '01 · 描述结果') }}</span><h3>{{ t('courseEvolution.workspace.requestTitle', '这次想让课程怎么变？') }}</h3></div><small>{{ t('courseEvolution.workspace.requestHint', '不用写成指令，直接说你想得到的结果') }}</small></div>
                <form @submit.prevent="submitRequest">
                  <textarea ref="requestInputRef" v-model="requestText" rows="6" :placeholder="t('courseEvolution.workspace.requestPlaceholder', '例如：以后所有例子都讲得更详细一点，并同步更新讲稿和 PPT')" :disabled="store.generating || contextUnavailable" />
                  <div class="request-suggestions" aria-label="常用修改示例"><button v-for="item in requestSuggestions" :key="item" type="button" @click="requestText = item">{{ item }}</button></div>
                  <p v-if="store.generationError || actionError" class="inline-error" role="alert"><TriangleAlert :size="15" />{{ store.generationError || actionError }}</p>
                  <footer><span><ShieldCheck :size="15" />{{ t('courseEvolution.workspace.noDirectWrite', '先分析影响，确认前不改正式课程') }}</span><button type="submit" class="button-primary button-submit" :disabled="store.generating || !requestText.trim() || contextUnavailable"><Sparkles :size="16" />{{ t('courseEvolution.workspace.startAnalysis', '分析全课影响') }}</button></footer>
                </form>
                <section class="recent-changes">
                  <header><History :size="16" /><strong>{{ t('courseEvolution.workspace.recentChanges', '最近修改') }}</strong></header>
                  <ol v-if="recentPlans.length"><li v-for="plan in recentPlans" :key="plan.change_set_id"><span :data-status="plan.status">{{ recentPlanStatus(plan) }}</span><button type="button" @click="openPlan(plan.change_set_id)"><b>{{ plan.request_text }}</b><small>{{ formatPlanTime(plan) }}</small></button></li></ol>
                  <p v-else>{{ t('courseEvolution.workspace.noRecentChanges', '还没有课程修改记录') }}</p>
                </section>
              </section>
              <aside class="asset-ledger" aria-live="polite">
                <header><div><span>{{ t('courseEvolution.workspace.courseIndex', '课程索引') }}</span><strong>{{ contextStatusTitle }}</strong></div><LoaderCircle v-if="store.contextLoading" :size="17" class="spinning" /><CircleCheckBig v-else-if="context?.ready" :size="18" /><TriangleAlert v-else :size="18" /></header>
                <p>{{ contextStatusDetail }}</p>
                <ul><li v-for="asset in contextAssets" :key="asset.asset_type"><component :is="assetIcon(asset.asset_type)" :size="16" /><div><b>{{ asset.label }}</b><small>{{ assetStateLabel(asset.state) }}</small></div><strong>{{ asset.count || '—' }}</strong></li></ul>
                <footer v-if="context?.summary"><span>{{ context.summary.outline_nodes }} {{ t('courseEvolution.workspace.outlineUnits', '个结构节点') }}</span><span>{{ context.summary.indexed_units }} {{ t('courseEvolution.workspace.indexedUnits', '个已索引单元') }}</span></footer>
              </aside>
            </main>

            <main v-else-if="workspaceState === 'scanning'" class="scanning-state" aria-live="polite">
              <section class="scan-main">
                <div class="scan-heading"><span><ScanSearch :size="21" /></span><div><small>{{ t('courseEvolution.workspace.scanningKicker', '正在分析全课') }}</small><h3>{{ t('courseEvolution.workspace.scanRequestTitle', '正在理解要求并定位所有受影响内容') }}</h3></div></div>
                <div class="scan-line"><span /></div>
                <dl><div><dt>{{ t('courseEvolution.workspace.scanIndex', '索引召回') }}</dt><dd>{{ context?.summary?.indexed_units || 0 }} {{ t('courseEvolution.workspace.units', '个单元') }}</dd></div><div><dt>{{ t('courseEvolution.workspace.scanRelations', '关系扩展') }}</dt><dd>{{ t('courseEvolution.workspace.crossAssets', '跨大纲与教学资产') }}</dd></div><div><dt>{{ t('courseEvolution.workspace.scanJudgement', 'AI 判断') }}</dt><dd>{{ t('courseEvolution.workspace.keepRealImpact', '保留真实影响') }}</dd></div></dl>
                <p><ShieldCheck :size="15" />{{ t('courseEvolution.workspace.scanGuard', '此阶段只建立影响计划，不写入正式课程。') }}</p>
              </section>
              <aside><header>{{ t('courseEvolution.workspace.scanningAssets', '正在检查') }}</header><ul><li v-for="(asset, index) in availableContextAssets" :key="asset.asset_type" :style="{ '--scan-delay': `${index * 90}ms` }"><component :is="assetIcon(asset.asset_type)" :size="16" /><span>{{ asset.label }}</span><Check :size="14" /></li></ul></aside>
            </main>

            <main v-else-if="workspaceState === 'interpreting'" class="clarification-state">
              <section><div class="clarification-heading"><BrainCircuit :size="22" /><div><small>{{ t('courseEvolution.workspace.interpretingKicker', 'AI 已完成初步理解') }}</small><h3>{{ interpretedGoal }}</h3></div></div><p>{{ t('courseEvolution.workspace.clarificationHint', '结构变化会影响大量内容，下面的信息需要先确认。') }}</p><ol><li v-for="question in planning?.intent.blocking_questions || []" :key="question">{{ question }}</li></ol><button type="button" class="button-primary" @click="openCorrection"><PencilLine :size="15" />{{ t('courseEvolution.workspace.answerAndReanalyze', '补充说明并重新分析') }}</button></section>
            </main>

            <div v-else-if="workspaceState === 'content'" class="review-layout">
              <aside class="impact-nav">
                <header><small>{{ t('courseEvolution.workspace.impactScope', '影响范围') }}</small><strong>{{ affectedUnits.length }} {{ impactUnitNoun }}</strong><p>{{ analysisModeLabel }}</p></header>
                <nav><button v-for="asset in affectedAssets" :key="asset.key" type="button" :class="{ active: selectedAsset === asset.key }" @click="selectedAsset = asset.key"><component :is="assetIcon(asset.key)" :size="16" /><span>{{ asset.label }}</span><b>{{ asset.count }}</b></button></nav>
                <section v-if="protectedRequirements.length" class="protected-scope"><ShieldCheck :size="16" /><div><b>{{ t('courseEvolution.workspace.protectedRequirements', '必须保留') }}</b><p>{{ protectedRequirements.join('；') }}</p></div></section>
                <dl class="scope-counts"><div><dt>{{ t('courseEvolution.workspace.included', '纳入') }}</dt><dd>{{ selectedImpactCount }}</dd></div><div><dt>{{ t('courseEvolution.workspace.excluded', '排除') }}</dt><dd>{{ excludedUnitIds.size }}</dd></div></dl>
              </aside>
              <section class="impact-review">
                <header class="review-header"><div><small>{{ selectedAssetLabel }}</small><h3>{{ reviewImpactTitle }}</h3></div><span><ShieldCheck :size="13" />{{ t('courseEvolution.workspace.formalUnchanged', '正式内容未改变') }}</span></header>
                <div class="impact-list">
                  <article v-for="item in visibleAffectedUnits" :key="item.migration_id" :class="{ excluded: !isUnitSelected(item.migration_id) }">
                    <label class="impact-check"><input type="checkbox" :checked="isUnitSelected(item.migration_id)" @change="toggleUnit(item.migration_id)" /><span /></label>
                    <div class="impact-copy"><header><div><small>{{ assetLabel(item.asset_type) }}</small><h4>{{ item.title }}</h4></div><span :data-disposition="item.disposition">{{ dispositionLabel(item.disposition) }}</span></header><p class="impact-reason">{{ item.reason }}</p><section v-if="item.before_preview" class="source-preview"><small>{{ t('courseEvolution.workspace.currentSource', '当前内容摘录') }}</small><p>{{ item.before_preview }}</p></section><footer><span v-if="item.source_state === 'stale'"><TriangleAlert :size="13" />{{ t('courseEvolution.workspace.sourceStale', '来源已落后于上游') }}</span><span>{{ confidenceLabel(item.confidence) }}</span></footer></div>
                  </article>
                  <p v-if="!visibleAffectedUnits.length" class="empty-impact">{{ t('courseEvolution.workspace.noAffectedForAsset', '这一类资产没有被判定为必改内容。') }}</p>
                </div>
                <footer class="review-actionbar"><div><strong v-if="scopeSaved"><CircleCheckBig :size="16" />{{ t('courseEvolution.workspace.scopeSaved', '影响范围已保存') }}</strong><p>{{ t('courseEvolution.workspace.reviewBoundary', '此处只保存影响范围，正式课程和各项资产仍未改变。') }}</p></div><button type="button" class="button-secondary" @click="startNewRequest">{{ t('courseEvolution.workspace.newChange', '重新提出要求') }}</button><button type="button" class="button-primary" :disabled="store.actingId === focusedPlan?.change_set_id || selectedImpactCount === 0" @click="saveScopeReview"><LoaderCircle v-if="store.actingId === focusedPlan?.change_set_id" :size="15" class="spinning" /><Check v-else :size="15" />{{ scopeSaved ? t('courseEvolution.workspace.updateScope', '更新范围') : t('courseEvolution.workspace.saveScope', '保存影响范围') }}</button></footer>
              </section>
            </div>

            <div v-else-if="workspaceState === 'structure'" class="structure-layout">
              <section class="structure-review">
                <header class="review-header"><div><small>{{ t('courseEvolution.workspace.structureKicker', '结构变化') }}</small><h3>{{ t('courseEvolution.workspace.compareCourseTree', '先核对新旧课程树，再决定内容迁移') }}</h3></div><span><TriangleAlert :size="13" />{{ t('courseEvolution.workspace.structureFirst', '结构优先') }}</span></header>
                <div class="tree-comparison"><section><header><BookOpenText :size="16" /><b>{{ t('courseEvolution.workspace.currentTree', '当前课程树') }}</b></header><ol><li v-for="node in currentOutline" :key="node.node_id" :style="{ '--tree-level': Math.max(0, Number(node.node_level || 1) - 1) }"><span />{{ node.node_name }}</li></ol></section><ArrowRight :size="19" /><section class="proposed-tree"><header><GitMerge :size="16" /><b>{{ t('courseEvolution.workspace.proposedTree', '调整后课程树') }}</b></header><ol v-if="proposedOutline.length"><li v-for="(node, index) in proposedOutline" :key="node.provisional_id || node.node_id || index" :style="{ '--tree-level': treeLevel(node) }"><span />{{ node.title || node.node_name }}</li></ol><p v-else>{{ t('courseEvolution.workspace.proposedTreePending', 'AI 已识别结构影响，但还需要你的补充才能形成可靠的新课程树。') }}</p></section></div>
              </section>
              <aside class="migration-panel"><header><small>{{ t('courseEvolution.workspace.migrationKicker', '迁移判断') }}</small><strong>{{ t('courseEvolution.workspace.migrationTitle', '原内容如何处理') }}</strong></header><dl><div v-for="item in migrationSummary" :key="item.key"><dt>{{ item.label }}</dt><dd>{{ item.count }}</dd></div></dl><section v-if="migrationReviewItems.length"><header><TriangleAlert :size="15" /><b>{{ t('courseEvolution.workspace.needsReview', '需要老师判断') }}</b></header><ul><li v-for="item in migrationReviewItems.slice(0, 8)" :key="item.migration_id">{{ item.title }}：{{ item.reason }}</li></ul></section><p><ShieldCheck :size="15" />{{ t('courseEvolution.workspace.structureReviewHint', '确认的是新结构和迁移原则，不是直接覆盖原课程。') }}</p><button type="button" class="button-primary" :disabled="store.generating" @click="openCorrection"><PencilLine :size="15" />{{ t('courseEvolution.workspace.refineStructure', '调整结构理解') }}</button></aside>
            </div>

            <main v-else class="receipt-state"><section><CircleCheckBig :size="26" /><small>{{ t('courseEvolution.workspace.appliedKicker', '应用完成') }}</small><h3>{{ applicationTitle }}</h3><p>{{ rawRequest }}</p><dl><div><dt>{{ t('courseEvolution.workspace.appliedItems', '已更新') }}</dt><dd>{{ receiptSummary.applied }}</dd></div><div><dt>{{ t('courseEvolution.workspace.failedItems', '失败') }}</dt><dd>{{ receiptSummary.failed }}</dd></div><div><dt>{{ t('courseEvolution.workspace.unchangedItems', '未变化') }}</dt><dd>{{ receiptSummary.unchanged }}</dd></div></dl><button type="button" class="button-primary" @click="startNewRequest"><Sparkles :size="15" />{{ t('courseEvolution.workspace.newChange', '继续修改课程') }}</button></section></main>
          </div>
        </section>
      </div>
    </Transition>
  </Teleport>
</template>

<script setup lang="ts">
import { computed, nextTick, ref, watch, type Component } from 'vue'
import { ArrowRight, BookOpenText, BookText, BrainCircuit, Check, CircleCheckBig, ClipboardList, FileQuestion, GitBranchPlus, GitMerge, History, LoaderCircle, PencilLine, Presentation, RefreshCw, ScanSearch, ScrollText, ShieldCheck, Sparkles, TriangleAlert, X } from 'lucide-vue-next'
import { t } from '../shared/i18n'
import { useCourseEvolutionStore, type CourseEvolutionApplicationPresentation, type CourseEvolutionPlan, type TeacherCourseChangeContext } from '../stores/courseEvolution'

type WorkspaceState = 'request' | 'scanning' | 'interpreting' | 'content' | 'structure' | 'applied'
type ContextAsset = TeacherCourseChangeContext['assets'][number]
type AffectedUnit = { migration_id: string; unit_id: string; asset_type: string; unit_type: string; title: string; before_preview: string; section_ids: string[]; source_state: string; disposition: string; reason: string; confidence: number; candidate_status: string }

const props = withDefaults(defineProps<{ modelValue: boolean; courseId: string; sectionId?: string; courseTitle?: string; sectionTitle?: string; focusPlanId?: string }>(), { sectionId: '', courseTitle: '', sectionTitle: '', focusPlanId: '' })
const emit = defineEmits<{ 'update:modelValue': [value: boolean]; courseApplied: [presentation: CourseEvolutionApplicationPresentation] }>()
const store = useCourseEvolutionStore()
const workspaceRef = ref<HTMLElement | null>(null)
const requestInputRef = ref<HTMLTextAreaElement | null>(null)
const previousFocus = ref<HTMLElement | null>(null)
const requestText = ref('')
const correctionText = ref('')
const correctionOpen = ref(false)
const actionError = ref('')
const selectedAsset = ref('')
const selectedPlanId = ref('')
const forceRequest = ref(false)
const excludedUnitIds = ref<Set<string>>(new Set())
const titleId = `course-change-${Math.random().toString(36).slice(2)}`

const context = computed(() => store.courseContext)
const courseLabel = computed(() => props.courseTitle || context.value?.course_title || t('courseEvolution.workspace.currentCourse', '当前课程'))
const focusedPlan = computed(() => {
  const preferredId = selectedPlanId.value || props.focusPlanId
  if (preferredId) {
    const preferred = store.plans.find(item => item.change_set_id === preferredId || item.plan_id === preferredId)
    if (preferred?.teacher_change_planning) return preferred
  }
  return [...store.plans].reverse().find(item => item.teacher_change_planning) || null
})
const planning = computed(() => focusedPlan.value?.teacher_change_planning || null)
const hasApplicationReceipt = computed(() => Object.keys(focusedPlan.value?.application_receipt || {}).length > 0)
const hasUndoReceipt = computed(() => Object.keys(focusedPlan.value?.undo_receipt || {}).length > 0)
const workspaceState = computed<WorkspaceState>(() => {
  if (store.generating) return 'scanning'
  if (forceRequest.value || !focusedPlan.value || focusedPlan.value.status === 'rejected') return 'request'
  if (['applied', 'undone'].includes(focusedPlan.value.status) || hasApplicationReceipt.value || hasUndoReceipt.value) return 'applied'
  if (planning.value?.status === 'needs_clarification') return 'interpreting'
  if (planning.value?.structural_operations.length || planning.value?.execution_strategies.includes('structural_regeneration')) return 'structure'
  return 'content'
})
const journeySteps = computed(() => [{ index: 1, label: t('courseEvolution.workspace.journeyRequest', '描述要求') }, { index: 2, label: t('courseEvolution.workspace.journeyAnalyze', '分析影响') }, { index: 3, label: t('courseEvolution.workspace.journeyReview', '核对方案') }, { index: 4, label: t('courseEvolution.workspace.journeyApply', '生成与应用') }])
const currentJourneyStep = computed(() => ({ request: 1, scanning: 2, interpreting: 2, content: 3, structure: 3, applied: 4 })[workspaceState.value])
const rawRequest = computed(() => planning.value?.intent.raw_request || focusedPlan.value?.request_text || '')
const interpretedGoal = computed(() => planning.value?.intent.interpreted_goal || focusedPlan.value?.expected_effect || rawRequest.value)
const protectedRequirements = computed(() => [...(planning.value?.intent.hard_constraints || []), ...(planning.value?.intent.protected_requirements || [])])
const contextUnavailable = computed(() => store.contextLoading || !context.value?.ready)
const contextAssets = computed(() => context.value?.assets || emptyAssets)
const availableContextAssets = computed(() => contextAssets.value.filter(item => item.state !== 'missing'))
const contextStatusTitle = computed(() => store.contextLoading ? t('courseEvolution.workspace.indexLoading', '正在连接课程资产') : context.value?.ready ? t('courseEvolution.workspace.indexReady', '已连接真实课程资产') : t('courseEvolution.workspace.indexUnavailable', '尚无可分析内容'))
const contextStatusDetail = computed(() => context.value?.readiness_message || t('courseEvolution.workspace.indexInitial', '打开工作台时自动读取各项课程资产'))
const affectedUnits = computed<AffectedUnit[]>(() => Array.isArray(focusedPlan.value?.impact_summary?.affected_units) ? focusedPlan.value?.impact_summary?.affected_units as AffectedUnit[] : [])
const affectedAssets = computed(() => { const counts = new Map<string, number>(); affectedUnits.value.forEach(item => counts.set(item.asset_type, (counts.get(item.asset_type) || 0) + 1)); return [...counts].map(([key, count]) => ({ key, count, label: assetLabel(key) })) })
const visibleAffectedUnits = computed(() => affectedUnits.value.filter(item => item.asset_type === selectedAsset.value))
const selectedAssetLabel = computed(() => affectedAssets.value.find(item => item.key === selectedAsset.value)?.label || '')
const selectedImpactCount = computed(() => affectedUnits.value.length - excludedUnitIds.value.size)
const analysisModeLabel = computed(() => focusedPlan.value?.impact_summary?.analysis_mode === 'ai_ranked' ? t('courseEvolution.workspace.aiRanked', '索引召回后由 AI 判断') : t('courseEvolution.workspace.indexFallback', '当前为索引候选，需重点复核'))
const isIndexFallback = computed(() => focusedPlan.value?.impact_summary?.analysis_mode !== 'ai_ranked')
const impactUnitNoun = computed(() => isIndexFallback.value ? t('courseEvolution.workspace.candidateUnits', '个待复核候选') : t('courseEvolution.workspace.affectedUnits', '个受影响单元'))
const reviewImpactTitle = computed(() => isIndexFallback.value ? t('courseEvolution.workspace.reviewCandidates', '核对这些候选为什么被索引召回') : t('courseEvolution.workspace.reviewImpact', '核对 AI 为什么认为这些内容会受影响'))
const scopeReview = computed(() => focusedPlan.value?.impact_summary?.scope_review || null)
const scopeSaved = computed(() => Boolean(scopeReview.value?.reviewed_at))
const currentOutline = computed(() => Array.isArray(focusedPlan.value?.impact_summary?.current_outline) ? focusedPlan.value?.impact_summary?.current_outline : context.value?.outline || [])
const proposedOutline = computed(() => Array.isArray(focusedPlan.value?.impact_summary?.proposed_outline) ? focusedPlan.value?.impact_summary?.proposed_outline : [])
const migrationSummary = computed(() => ([['reuse_exact', '原样保留'], ['reuse_rebind', '迁移重绑'], ['rewrite_partial', '局部改写'], ['regenerate', '重新生成'], ['retire', '停用'], ['blocked', '阻断']] as string[][]).map(([key, label]) => ({ key, label, count: affectedUnits.value.filter(item => item.disposition === key).length })))
const migrationReviewItems = computed(() => affectedUnits.value.filter(item => ['blocked', 'regenerate', 'retire'].includes(item.disposition)))
const recentPlans = computed(() => [...store.plans].reverse().filter(item => item.teacher_change_planning).slice(0, 4))
const applicationTitle = computed(() => focusedPlan.value?.status === 'undone' ? t('courseEvolution.workspace.undoneTitle', '本次修改已撤销') : t('courseEvolution.workspace.appliedTitle', '课程已按确认结果更新'))
const receiptSummary = computed(() => ({ applied: Number(focusedPlan.value?.application_receipt?.applied_count ?? focusedPlan.value?.applied_block_ids?.length ?? 0), failed: Number(focusedPlan.value?.application_receipt?.failed_count ?? 0), unchanged: Number(focusedPlan.value?.application_receipt?.unchanged_count ?? 0) }))
const requestSuggestions = ['所有案例都补充完整推导、反例和适用边界', '按新的教学逻辑重构章节，并迁移可以保留的内容', '统一更新大纲、教案、讲稿和 PPT 中过时的模型版本']
const emptyAssets = ([['outline', '课程大纲'], ['lesson_plan', '教案'], ['script', '讲稿'], ['ppt', 'PPT'], ['question_bank', '题库']] as string[][]).map(([asset_type, label]) => ({ asset_type, label, state: 'missing', count: 0, source: '', revision: '' })) as ContextAsset[]

watch(affectedAssets, items => { if (!items.some(item => item.key === selectedAsset.value)) selectedAsset.value = items[0]?.key || '' }, { immediate: true })
watch(() => focusedPlan.value?.change_set_id, () => { const saved = scopeReview.value?.excluded_migration_ids; excludedUnitIds.value = new Set(Array.isArray(saved) ? saved.map(String) : []) })
watch(() => props.modelValue, async open => { if (!open) return; previousFocus.value = document.activeElement instanceof HTMLElement ? document.activeElement : null; forceRequest.value = false; selectedPlanId.value = props.focusPlanId; await reloadWorkspace(); await nextTick(); workspaceRef.value?.focus(); if (workspaceState.value === 'request') requestInputRef.value?.focus() }, { immediate: true })

function assetIcon(value: string): Component { return ({ outline: BookText, course_content: BookOpenText, lesson_plan: ClipboardList, script: ScrollText, teacher_script: ScrollText, ppt: Presentation, slide_deck: Presentation, question_bank: FileQuestion } as Record<string, Component>)[value] || BookText }
function assetLabel(value: string) { return ({ outline: '课程大纲', course_content: '课程正文', lesson_plan: '教案', script: '讲稿', teacher_script: '讲稿', ppt: 'PPT', slide_deck: 'PPT', question_bank: '题库' } as Record<string, string>)[value] || value }
function assetStateLabel(value: ContextAsset['state']) { return ({ available: t('courseEvolution.workspace.assetAvailable', '可分析'), partial: t('courseEvolution.workspace.assetPartial', '部分完成'), missing: t('courseEvolution.workspace.assetMissing', '尚未生成'), stale: t('courseEvolution.workspace.assetStale', '需要同步') } as Record<string, string>)[value] }
function dispositionLabel(value: string) { return ({ reuse_exact: '保留', reuse_rebind: '迁移重绑', rewrite_partial: '局部改写', regenerate: '重新生成', retire: '停用', blocked: '需判断' } as Record<string, string>)[value] || value }
function confidenceLabel(value: number) { return value >= .8 ? t('courseEvolution.workspace.highConfidence', '高置信度') : value >= .6 ? t('courseEvolution.workspace.mediumConfidence', '中等置信度') : t('courseEvolution.workspace.lowConfidence', '需要重点复核') }
function treeLevel(node: Record<string, any>) {
  const byId = new Map(proposedOutline.value.map(item => [String(item.provisional_id || item.node_id || ''), item]))
  const seen = new Set<string>()
  let parentId = String(node.parent_ref || node.parent_node_id || 'root')
  let level = 0
  while (parentId && parentId !== 'root' && !seen.has(parentId) && level < 6) {
    seen.add(parentId)
    level += 1
    const parent = byId.get(parentId)
    parentId = String(parent?.parent_ref || parent?.parent_node_id || 'root')
  }
  return level
}
function isUnitSelected(id: string) { return !excludedUnitIds.value.has(id) }
function toggleUnit(id: string) { const next = new Set(excludedUnitIds.value); if (next.has(id)) next.delete(id); else next.add(id); excludedUnitIds.value = next }
function recentPlanStatus(plan: CourseEvolutionPlan) { if (plan.status === 'applied') return '已应用'; if (plan.status === 'undone') return '已撤销'; if (plan.status === 'rejected') return '已放弃'; return plan.impact_summary?.scope_review?.reviewed_at ? '已审阅' : '待审阅' }
function formatPlanTime(plan: CourseEvolutionPlan) { const value = plan.teacher_change_planning?.updated_at || plan.teacher_change_planning?.created_at; if (!value) return ''; const date = new Date(value); return Number.isNaN(date.getTime()) ? value : new Intl.DateTimeFormat('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }).format(date) }
async function reloadWorkspace() { actionError.value = ''; try { await Promise.all([store.refreshProgress(props.courseId), store.loadCourseContext(props.courseId)]) } catch (error: any) { actionError.value = String(error?.response?.data?.detail?.message || error?.message || '课程资产读取失败，请重试。') } }
async function submitRequest() { if (!requestText.value.trim() || contextUnavailable.value) return; actionError.value = ''; forceRequest.value = false; try { await store.createCoursePlan({ instruction: requestText.value.trim() }); selectedPlanId.value = '' } catch (error: any) { actionError.value = String(error?.response?.data?.detail?.message || error?.message || '全课影响分析失败，请重试。'); forceRequest.value = true } }
function openCorrection() { correctionText.value = ''; correctionOpen.value = true }
async function submitCorrection() { if (!correctionText.value.trim()) return; const combined = `${rawRequest.value}\n补充修正：${correctionText.value.trim()}`.trim(); actionError.value = ''; try { await store.createCoursePlan({ instruction: combined }); correctionOpen.value = false; selectedPlanId.value = '' } catch (error: any) { actionError.value = String(error?.response?.data?.detail?.message || error?.message || '重新分析失败，请重试。') } }
async function saveScopeReview() { if (!focusedPlan.value) return; actionError.value = ''; try { await store.reviewCoursePlan(focusedPlan.value.change_set_id, affectedUnits.value.filter(item => !excludedUnitIds.value.has(item.migration_id)).map(item => item.migration_id)) } catch (error: any) { actionError.value = String(error?.response?.data?.detail?.message || error?.message || '影响范围保存失败，请重试。') } }
function startNewRequest() { forceRequest.value = true; selectedPlanId.value = ''; requestText.value = ''; correctionOpen.value = false; actionError.value = ''; store.generationError = ''; nextTick(() => requestInputRef.value?.focus()) }
function openPlan(id: string) { selectedPlanId.value = id; forceRequest.value = false }
function close() { emit('update:modelValue', false); nextTick(() => previousFocus.value?.focus()) }
function handleKeydown(event: KeyboardEvent) { if (event.key === 'Escape') { event.preventDefault(); close(); return } if (event.key !== 'Tab' || !workspaceRef.value) return; const focusable = [...workspaceRef.value.querySelectorAll<HTMLElement>('button:not([disabled]), textarea:not([disabled]), input:not([disabled]), [href], [tabindex]:not([tabindex="-1"])')].filter(item => !item.hasAttribute('hidden')); if (!focusable.length) { event.preventDefault(); workspaceRef.value.focus(); return } const first = focusable[0]!; const last = focusable[focusable.length - 1]!; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus() } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus() } }
</script>

